"""Small standard-library JSON Schema validator for config-file validation.

Supports the constraints most often used in configuration schemas. Returns
human-readable errors in deterministic traversal order.
"""
import re


def validate(instance, schema, path="(root)"):
    errors = []
    if not isinstance(schema, dict):
        return [f"{path}: invalid schema"]

    def add(msg):
        errors.append(f"{path}: {msg}")

    typ = schema.get("type")
    typemap = {"object": dict, "array": list, "string": str, "boolean": bool,
               "integer": int, "number": (int, float), "null": type(None)}
    if typ in typemap:
        pytype = typemap[typ]
        ok = isinstance(instance, pytype)
        if typ in ("integer", "number") and isinstance(instance, bool):
            ok = False
        if not ok:
            return [f"{path}: Expected {typ}"]
    if "const" in schema and instance != schema["const"]:
        add("Value must be equal to the const value")
    if "enum" in schema and instance not in schema["enum"]:
        add("Value must be one of the enum values")
    if isinstance(instance, dict):
        props = schema.get("properties", {})
        for key, sub in props.items():
            if key in instance:
                errors.extend(validate(instance[key], sub, f"{path}.{key}" if path != "(root)" else str(key)))
        for key in schema.get("required", []):
            if key not in instance:
                errors.append(f"{path}: Missing required property {key}")
        additional = schema.get("additionalProperties", True)
        for key in instance:
            if key not in props:
                if additional is False:
                    errors.append(f"{path}: Additional property {key} is not allowed")
                elif isinstance(additional, dict):
                    errors.extend(validate(instance[key], additional, f"{path}.{key}"))
        if "minProperties" in schema and len(instance) < schema["minProperties"]:
            add(f"Object must have at least {schema['minProperties']} properties")
        if "maxProperties" in schema and len(instance) > schema["maxProperties"]:
            add(f"Object must have at most {schema['maxProperties']} properties")
    elif isinstance(instance, list):
        items = schema.get("items")
        for i, val in enumerate(instance):
            if isinstance(items, dict):
                errors.extend(validate(val, items, f"{path}[{i}]"))
        if "minItems" in schema and len(instance) < schema["minItems"]:
            add(f"Array must have at least {schema['minItems']} items")
        if "maxItems" in schema and len(instance) > schema["maxItems"]:
            add(f"Array must have at most {schema['maxItems']} items")
    elif isinstance(instance, str):
        if "minLength" in schema and len(instance) < schema["minLength"]:
            add(f"String length must be greater than or equal to {schema['minLength']}")
        if "maxLength" in schema and len(instance) > schema["maxLength"]:
            add(f"String length must be less than or equal to {schema['maxLength']}")
        if "pattern" in schema and not re.search(schema["pattern"], instance):
            add(f"String must match pattern {schema['pattern']}")
    elif isinstance(instance, (int, float)) and not isinstance(instance, bool):
        for key, cmp, desc in (("minimum", lambda a,b:a>=b, "greater than or equal to"),
                               ("maximum", lambda a,b:a<=b, "less than or equal to"),
                               ("exclusiveMinimum", lambda a,b:a>b, "greater than"),
                               ("exclusiveMaximum", lambda a,b:a<b, "less than")):
            if key in schema and not cmp(instance, schema[key]):
                add(f"Must be {desc} {schema[key]}")
        if "multipleOf" in schema and schema["multipleOf"] and instance % schema["multipleOf"]:
            add(f"Must be a multiple of {schema['multipleOf']}")
    for key, pred, msg in (("allOf", lambda x: all(x), ""),):
        if key in schema:
            for sub in schema[key]: errors.extend(validate(instance, sub, path))
    if "anyOf" in schema and not any(not validate(instance, s, path) for s in schema["anyOf"]):
        add("Value must match at least one schema in anyOf")
    if "oneOf" in schema:
        n = sum(not validate(instance, s, path) for s in schema["oneOf"])
        if n != 1: add("Value must match exactly one schema in oneOf")
    if "not" in schema and not validate(instance, schema["not"], path):
        add("Value must not match schema")
    return errors
