    root={}; table=root
    raw_lines=[]; pending=''; start_line=1; depth=0; quote=None; escape=False
    for no,raw in enumerate(text.splitlines(),1):
        if not pending: start_line=no
        pending += (' ' if pending else '') + raw
        quote=None; escape=False; depth=0
        for ch in pending:
            if escape: escape=False; continue
            if ch=='\\' and quote=='"': escape=True; continue
            if quote:
                if ch==quote: quote=None
            elif ch in ('"', "'"): quote=ch
            elif ch=='[': depth+=1
            elif ch==']': depth-=1
        if depth<=0 and quote is None:
            raw_lines.append((start_line,pending)); pending=''
    if pending: raise ValueError(f'invalid TOML at line {start_line}')
    for line_no,line in raw_lines:
        # Strip comments outside quoted strings.
        quote=None; esc=False; cut=len(line)
        for i,c in enumerate(line):
            if esc: esc=False; continue
            if c=='\\' and quote=='"': esc=True; continue
            if quote:
                if c==quote: quote=None
            elif c in ('"', "'"): quote=c
            elif c=='#': cut=i; break
        line=line[:cut].strip()
        if not line: continue
        m=re.fullmatch(r'\[([^\]]+)\]',line)
        if m:
            table=root
            for part in m.group(1).split('.'):
                part=part.strip().strip('"\'')
