def find_config(cwd=None, explicit=None, disabled=False):
    if disabled: return None
    if explicit:
        return os.path.abspath(os.path.join(cwd or os.getcwd(), explicit))
    here=os.path.abspath(cwd or os.getcwd())
    while True:
        p=os.path.join(here,'.cfv.toml')
        if os.path.isfile(p): return p
        parent=os.path.dirname(here)
        if parent==here: return None
        here=parent


def load_config(cwd=None, explicit=None, disabled=False):
    """Return (dict, path, error). error is a user-facing reason string."""
    path=find_config(cwd,explicit,disabled)
    if path is None: return {},None,None
